def get_waveform_name(wave_no):
    """Returns waveform name (str) or 'Unknown' if not found."""
    entry = WAVEFORMS.get(wave_no)
    if entry is None: return f'Unknown ({wave_no})'
    return entry[0]


def get_waveform(wave_no):
    """Returns dict with name, main_cat, sub_cat."""
    entry = WAVEFORMS.get(wave_no)
    if entry is None: return None
    return {'name': entry[0], 'main_cat': entry[1], 'sub_cat': entry[2]}


def waveforms_by_category(main_cat=None, sub_cat=None):
    """Returns sorted list of (wave_no, name) filtered by category."""
    result = []
    for k, (name, mc, sc) in WAVEFORMS.items():
        if main_cat and mc != main_cat: continue
        if sub_cat and sc != sub_cat: continue
        result.append((k, name))
    return sorted(result)


def get_main_categories():
    """Returns sorted list of unique main categories."""
    return sorted(set(v[1] for v in WAVEFORMS.values()))


def get_sub_categories(main_cat=None):
    """Returns sorted list of unique sub categories (filtered by main if given)."""
    if main_cat:
        return sorted(set(v[2] for v in WAVEFORMS.values() if v[1] == main_cat))
    return sorted(set(v[2] for v in WAVEFORMS.values()))


if __name__ == '__main__':
    print(f"Total waveforms: {len(WAVEFORMS)}")
    print(f"Main categories: {get_main_categories()}")
    print(f"\nSamples:")
    for k in [1, 100, 1000, 5000]:
        if k in WAVEFORMS:
            print(f"  Wave {k}: {get_waveform_name(k)}")
